export const ERRORS=[20,-20,0,0,10,-10,0,0];
export function create(){return{actual:[40,65,48,90,55,72,30,85],order:[0,1,2,3,4,5,6,7],threshold:60,miss:8,falseAlarm:3};}
export function validate(s){if(!s||!Array.isArray(s.actual)||s.actual.length!==8||s.actual.some(x=>!Number.isFinite(x)||x<20||x>100)||!Array.isArray(s.order)||s.order.length!==8||new Set(s.order).size!==8||s.order.some(x=>!Number.isInteger(x)||x<0||x>7)||!Number.isFinite(s.threshold)||s.threshold<20||s.threshold>100||![s.miss,s.falseAlarm].every(x=>Number.isFinite(x)&&x>=0&&x<=20))throw Error('Invalid decision experiment');return s;}
export function swap(s,from,to){validate(s);if(![from,to].every(x=>Number.isInteger(x)&&x>=0&&x<8))throw Error('Unknown moment');const next=structuredClone(s);[next.order[from],next.order[to]]=[next.order[to],next.order[from]];return next;}
export function evaluate(s){validate(s);const rows=s.actual.map((actual,i)=>{const error=ERRORS[s.order[i]],forecast=actual+error,act=forecast>=s.threshold,need=actual>=s.threshold,kind=need&&!act?'miss':act&&!need?'falseAlarm':'correct';return{actual,error,forecast,act,need,kind,cost:kind==='correct'?0:s[kind]};});return{rows,mae:rows.reduce((a,r)=>a+Math.abs(r.error),0)/8,rmse:Math.sqrt(rows.reduce((a,r)=>a+r.error*r.error,0)/8),loss:rows.reduce((a,r)=>a+r.cost,0),misses:rows.filter(r=>r.kind==='miss').length,falseAlarms:rows.filter(r=>r.kind==='falseAlarm').length,alwaysAct:rows.filter(r=>!r.need).length*s.falseAlarm,neverAct:rows.filter(r=>r.need).length*s.miss};}
export function compare(s,baseline){return baseline?evaluate({...s,order:[...baseline.order]}):null;}
